// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the end-to-end architecture of this order sync and stock alert workflow.", "The store POSTs each order event to an n8n Webhook node. A Code node verifies the HMAC signature on the raw body, and an IF node rejects failures. The event ID goes into processed_events with INSERT … ON CONFLICT DO NOTHING, so duplicates stop there. A Respond to Webhook node then returns 200. A Switch node sends order-created events one way and cancellations or refunds another. Set/Edit Fields splits the order into line items, and Loop Over Items processes them in batches. Each line runs one atomic UPDATE … RETURNING. An IF node detects a reorder-point crossing and triggers Slack, WhatsApp and a purchase-draft sub-workflow that waits for approval. Retry-on-fail and an error workflow make sure no failure is silent."),
    s(5, "Why does the workflow return 200 after persisting the event instead of after all processing finishes?", "Store platforms expect a quick acknowledgement and resend if they time out. If we held the response until every line was decremented and every alert was sent, a slow Postgres or Slack call could push us past that timeout. The store would then resend an event we are already processing. So we do only the minimum: verify the signature, record the event ID durably, then answer 200. That gives the store a fast, honest acknowledgement, because the event is now safely on our side. Dedupe absorbs any resends that still happen. The trade-off is that processing failures are no longer visible to the store. That is why the error workflow, failed status and replay path are mandatory, not optional."),
    s(4, "How would you implement HMAC verification in n8n, and what pitfalls would you avoid?", "Configure the Webhook node so the raw body is available, because the signature is computed over the exact bytes the store sent. Re-serialising parsed JSON can change whitespace or key order and break the match. In a Code node, compute the HMAC with the shared secret using the algorithm the platform documents, then compare it with the header using a constant-time comparison such as crypto.timingSafeEqual. On self-hosted n8n you may need to allow the built-in crypto module for the Code node. Keep the secret in a credential or environment variable, never hard-coded in the node. An IF node rejects failures with a 401 and logs them. If the platform signs a timestamp, also reject requests that are too old to limit replay."),
    s(5, "What tables would you create in Postgres for this workflow, and what are their key columns?", "processed_events: event_id as the primary key, plus event type, order ID, status (received, done, failed), timestamps and the n8n execution ID. inventory: sku and location as the key, with on_hand and reorder_point. Optionally inventory_movements, with event_id, line id, sku, delta and created_at, and a unique constraint on event plus line. That table gives an audit trail and per-line idempotency. purchase_drafts: id, sku, suggested quantity, supplier, status (open, approved, rejected) and approval timestamps, with a partial unique index on sku where status is open. workflow_errors: execution ID, event ID, failing node, error message and time. Every guarantee the workflow makes, such as dedupe, no lost updates and one open draft, is backed by a constraint rather than by workflow logic alone."),
    s(4, "How do you detect a reorder-point crossing using only the result of the UPDATE?", "The UPDATE returns the new on_hand and the reorder_point. For a sale, the previous quantity is the new on_hand plus the line quantity. The IF node fires only when previous is above reorder_point and new is at or below it. Because the UPDATE is atomic, each row change has exactly one before and after. Two concurrent orders cannot both see the same crossing: only the update that moves the value across the threshold satisfies the condition. For example, with a reorder point of 5, an order of 3 that takes stock from 7 to 4 alerts. A later order of 1 that takes it from 4 to 3 does not. Cancellations add stock back, so they never fire a low-stock alert."),
    s(5, "An order has five lines and the Postgres update for line three fails after retries. What happens, and how do you make replay safe?", "Lines one and two are already committed, and the error workflow marks the event failed. A naive replay would decrement lines one and two again, because event-level dedupe only protects the whole event. There are two safe fixes. You can record each line in an inventory_movements table keyed on event ID plus line ID, in the same SQL statement as the update, for example a CTE that inserts the movement and updates inventory only if that insert succeeded. Or you can wrap all lines of one event in a single transaction so it is all or nothing. Per-line keys suit batched loops better. The replay then sets the event back to processing, skips the lines already applied and continues from line three."),
    s(4, "What happens if the UPDATE matches zero rows because the SKU is unknown, and how do you avoid a silent drop?", "In n8n, a Postgres query that returns no rows can produce no output items, so the downstream nodes simply do not run. The line disappears without any error, which breaks the rule against silent drops. To prevent this, enable Always Output Data on that node, or check the result count with an IF node. Then treat zero rows as a real failure: throw an error from a Code node, or route the line to an unmatched-SKU path. That path records it in Postgres, marks the event for attention and alerts Slack. Typical causes are a new product not yet synced, a SKU typo or a wrong location, and someone has to fix the data before replaying."),
    s(3, "Should the inventory update allow on_hand to go negative?", "It is a business decision with a technical consequence. The store has usually already accepted the order, so refusing the decrement does not undo the sale. It only makes our count wrong. I would normally let on_hand go negative, because a negative value honestly records oversold stock. Its reorder-point crossing still raises an alert, and an oversold flag can alert separately. The alternative is to add on_hand >= qty to the WHERE clause. That rejects the update, and the zero-row result must then go to an oversell path rather than being dropped. That approach fits when n8n is the source of truth for stock, but it needs a compensating action such as cancelling the order or putting it on backorder."),
    s(4, "What makes the cancellation and refund path harder than the order-created path?", "First, not every refund means stock is coming back. A refund for a damaged item or a partial money-only refund should not restock. So the path must look at line-level restock flags or quantities, not just the event type. Second, a cancellation must only restore stock that was actually decremented. If the original order failed or was never processed, adding stock back inflates inventory. I would check that inventory_movements holds the original lines before applying the reversal. Third, cancellations have their own event IDs, so they go through the same dedupe. Fourth, adding stock can lift a SKU back above its reorder point. That re-arms the alert, which is correct, and it may also make an open purchase draft unnecessary, so buyers should be told."),
    s(3, "How do you handle events arriving out of order, such as a cancellation processed before its order-created event?", "Webhooks are not guaranteed to arrive in order, and retries make reordering more likely. Keep per-order state, derived from processed_events or a small orders table, recording whether the order's decrements were applied. If a cancellation arrives for an order with no applied movements, do not add stock back. Record the cancellation as pending, or park it and retry it later with a Schedule-triggered sweep. When the order-created event then arrives, check for a recorded cancellation and skip the decrement entirely. Event timestamps or version numbers from the platform help resolve conflicts. The key rule is that every reversal is tied to a recorded forward movement and never applied blindly."),
    s(4, "How would you estimate the load this workflow must handle?", "I would start from the business's own numbers rather than guess. That means orders per day, average lines per order, and the peak-to-average ratio during sales or festival campaigns. As an illustration, if a store had 10,000 orders a day with 3 lines each, that is 30,000 inventory updates a day, well under one per second on average. A sale could multiply the peak many times over. Each line costs one small indexed UPDATE, which Postgres handles easily. The real limits are n8n execution overhead, concurrency and how many backlog events a replay releases at once. Alert volume is low by design, because only crossings alert. I would load-test with a replayed backlog at the expected peak before a big sale."),
    s(4, "When would you move this workflow to n8n queue mode, and how does it change the design?", "Move when a single main instance cannot keep up with peak executions, or when you need workers that can restart without losing work. In queue mode, the main or webhook process receives requests and puts executions on a Redis queue, and multiple workers run them. The design already copes with this. The atomic UPDATE prevents lost updates between workers, ON CONFLICT dedupe stops parallel duplicate deliveries, and a unique index protects open drafts. What to check: the configured concurrency per worker and the Postgres connection limits, because many workers times the pool size can exhaust connections. Waiting executions are stored in the database, so approvals survive worker restarts. Redis and Postgres themselves need monitoring and backups."),
    s(4, "How would you configure retry-on-fail on the writing nodes, and what are the risks?", "Enable retry-on-fail with a few attempts and a wait between them on Postgres, Slack, WhatsApp and the draft insert, to absorb transient network errors, rate limits and brief outages. Do not expect retries to fix permanent errors such as bad SQL, an invalid template or an unknown SKU. Those should fail fast to the error workflow. The main risk is retrying a non-idempotent write that actually committed but timed out on the response. A retried decrement would then double-count. Per-line movement keys make the UPDATE safe to retry. Alerts can duplicate on retry, which is tolerable but avoidable by recording that an alert was sent. Keep the total retry time bounded so executions do not pile up during an outage."),
    s(4, "What should the error workflow do, and how does replay work afterwards?", "The error workflow is set in the main workflow's settings and starts from an Error Trigger. That trigger receives details such as the execution ID, the failing node and the error message. It inserts a row into a workflow_errors table and sets the event's status in processed_events to failed. It then posts to the on-call Slack channel with the event ID, the node and a link to the execution. For replay, a person or a Schedule-triggered sweep picks up failed events, resets them to processing and re-runs the order logic. The original payload or a reference to it must be stored, because the store will not resend. Per-line idempotency makes partial replays safe. The error workflow should be very simple, so it does not fail itself."),
    s(4, "How do you guarantee only one open purchase draft per SKU when crossings for the same SKU can happen concurrently?", "A check-then-insert in the sub-workflow races under queue mode, because two executions can both see no open draft. Enforce it in the database instead, with a partial unique index on purchase_drafts(sku) where status = 'open'. The sub-workflow then runs INSERT … ON CONFLICT DO NOTHING RETURNING id. If a row comes back, this execution owns the draft and sends the approval link. If nothing comes back, a draft already exists, and it ends quietly or adds a note. Because the alert fires only on a crossing, concurrent crossings are rare anyway, but a constraint makes the guarantee absolute. When a draft is approved or rejected, its status changes, which frees the slot for a future crossing."),
    s(3, "The purchase-draft sub-workflow waits for approval. What issues come with long-running Wait nodes?", "A waiting execution is saved to the database and resumed when its resume URL is called, so it survives restarts. But waits can pile up if buyers ignore approvals. Set a time limit on the Wait node so it resumes after, for example, a few days. Then route that timeout path to a reminder or escalation, or mark the draft expired. The draft's status in Postgres should be the source of truth, not the existence of a waiting execution. That way, approving in another tool or cancelling the draft stays consistent. If the workflow is changed while executions are waiting, they resume on their saved version, so test changes carefully. Finally, make sure the resume URL can reach n8n through your proxy."),
    s(4, "How do you secure the approval link sent to the buyer?", "The resume URL is effectively a bearer token: anyone who has it can approve. Send it only through trusted channels, such as a direct Slack message or WhatsApp to the named buyer. Where the Wait node supports it, enable authentication on the resume webhook. Alternatively, point the link at a small approval page that checks the user's identity first. Make the approval idempotent: the draft moves from open to approved once, and a second click changes nothing. Record who approved and when. Use HTTPS only and give the link a time limit, ideally the Wait timeout. Do not put supplier pricing or other sensitive data in the URL query string, because links end up in logs and browser history."),
    s(3, "How should secrets and credentials be managed in this workflow?", "Postgres, Slack and WhatsApp Business Cloud access should use n8n credentials. These are stored encrypted and referenced by nodes, so they never appear in workflow JSON or exports. The HMAC secret should also live in a credential or environment variable, not in Code node source. Keep the n8n encryption key backed up and separate, because losing it makes stored credentials unreadable. Use a dedicated Postgres role with only the rights it needs on these tables, not a superuser. Scope the Slack bot to the needed channels. Rotate the WhatsApp access token and the store webhook secret on a schedule. Limit who can edit workflows, since editors can use any credential the workflow references."),
    s(4, "What privacy concerns exist here, and how would you minimise personal data?", "Order webhooks contain customer names, addresses, phone numbers and emails, but inventory only needs SKU, quantity and location. Strip PII early with Set/Edit Fields and store only what is needed in processed_events. n8n saves execution data, including full webhook payloads, so set execution saving and pruning deliberately. For example, prune successful executions after a short period and limit who can view executions. Alerts to Slack and WhatsApp should carry only the SKU, on-hand count and reorder point, never customer details. For an Indian business, align retention and handling with the DPDP Act and the company's privacy policy. If replay needs the payload, store a minimal one in Postgres with a retention period."),
    s(3, "What constraints does WhatsApp Business Cloud impose on the buyer alert?", "Business-initiated messages outside the 24-hour customer service window must use a pre-approved template. That is why the workflow sends a template message whose parameters are the SKU, on-hand count and reorder point. Templates are reviewed by Meta, so changing the wording means getting a template approved again. The buyer's number must be able to receive messages from the business, and messages may be charged depending on category and region, so check current pricing rather than assuming it is free. Rate limits and quality ratings apply, which is another reason alerts fire only on crossings. If WhatsApp fails after retries, Slack is still sent, and the error workflow records the failed notification."),
    s(4, "How do you stop notification failures from corrupting or blocking inventory processing?", "The inventory UPDATE is the critical write, and alerts are side effects that come after it. If Slack or WhatsApp fails, the stock count is already correct, so we must not undo it or replay the whole event in a way that decrements again. Retry notifications on their own nodes. If they still fail, record the alert as pending in Postgres and let the error path or a sweep resend it. Do not reset the event. Consider running notifications in a sub-workflow or with the node set to continue on error but log the failure, so one bad message does not stop the remaining line items in the loop. Recording that an alert was sent also prevents duplicate alerts on replay."),
    s(3, "After a two-hour outage, the store redelivers a large backlog of webhooks. How does the workflow cope?", "Redeliveries hit the Webhook node quickly. Each one does only signature check, dedupe insert and 200, so the acknowledgement path stays light. Events we already processed hit ON CONFLICT and stop. In queue mode, new events are spread across workers. Loop Over Items batches the line items within each order, and worker concurrency limits how many orders run at once, so Postgres is not flooded. Watch the connection count and lock contention on popular SKUs, because many orders for one SKU queue on the same row lock. Alerts stay limited because only crossings fire. Also check that events the error workflow marked failed during the outage get replayed once dependencies recover."),
    s(3, "What would you monitor to know this workflow is healthy?", "Track execution success and failure counts, and alert when failures exceed a threshold, not just on each error. Also watch the age of the oldest event in received or failed status, which catches stuck processing. Track webhook response time against the store's timeout, the rate of signature rejections (a spike may mean a rotated secret or an attack), and duplicate counts from ON CONFLICT. Other useful signals are queue length and worker health in queue mode, Postgres connection usage, and the number of waiting approvals older than their SLA. A daily reconciliation report comparing our on_hand with the store's stock catches silent drift that execution logs would never show."),
    s(3, "How would you extend the design to multiple warehouses or locations?", "Key inventory on SKU plus location, and make sure each line item carries the fulfilling location from the store payload. The UPDATE's WHERE clause then matches both. The reorder point becomes per location, so crossings and alerts are per location, and alerts should name the location. Purchase drafts need a decision: one open draft per SKU per location, or one per SKU across locations with a combined quantity. Enforce whichever you choose with the partial unique index. Transfers between locations are a separate event type. They decrement one location and increment the other, ideally in one transaction, so stock is never counted twice or lost."),
    s(3, "How do you detect and correct drift between your Postgres inventory and the actual stock?", "Drift comes from manual adjustments in the store, returns processed elsewhere, damaged goods or bugs. Add a Schedule-triggered workflow that pulls stock levels from the store or warehouse system, compares them with Postgres and reports differences above a tolerance to Slack. Corrections should be written as explicit adjustment movements with a reason, not silent overwrites, so the audit trail stays complete. If an adjustment moves a SKU across the reorder point, run the same crossing logic so alerts stay consistent. Decide which system is the source of truth for each field, so automatic corrections do not fight each other."),
    s(3, "How would you test this workflow before it goes live?", "Use a staging n8n instance and a staging Postgres database, with separate credentials and test Slack channels. Send signed sample payloads, including a bad signature, a duplicate event ID, an unknown SKU, a multi-line order and a cancellation before its order. Test the crossing logic at the boundaries: a value just above the reorder point, exactly at it, already below it, and a single order that jumps from well above to well below. Run concurrent orders for one SKU to confirm there are no lost updates and only one alert and draft. Force failures, such as stopping Postgres, to check that retries, the error workflow and replay work. Pinned test data in n8n helps you iterate node by node."),
    s(2, "Why use Postgres for inventory rather than Google Sheets?", "The guarantees depend on database features. An atomic UPDATE … RETURNING prevents lost updates under concurrency. A primary key with ON CONFLICT DO NOTHING gives reliable dedupe. Partial unique indexes enforce one open draft per SKU. Transactions make multi-line changes all or nothing. Google Sheets offers none of these. Two executions reading and writing a cell can overwrite each other, and API rate limits get in the way during bursts. Sheets is fine as a read-only view or report for buyers, fed from Postgres, but it should not be the system of record for stock counts that must never double-count."),
    s(2, "Why is the purchase draft a separate sub-workflow called via Execute Workflow?", "It has a different lifecycle. The order path should finish in seconds, while the draft path can wait days for approval on a Wait node. Keeping them apart means the order execution is not left waiting, and the draft logic can be reused, for example by the reconciliation workflow or a manual trigger. It can also be versioned and tested on its own. It also keeps the main workflow readable. I would usually not have the parent wait for the sub-workflow to finish, so a long approval does not hold the order execution open. Pass a clear input contract (SKU, location, on-hand count, reorder point) so callers stay decoupled."),
    s(2, "Could an AI model help with the suggested reorder quantity, and how would you add it safely?", "Yes, as advice, not as the decision. Inside the draft sub-workflow, an AI Agent or a basic chat model node using an OpenAI-compatible credential pointed at Vercel AI Gateway (https://ai-gateway.vercel.sh/v1) could look at recent sales, lead time and the supplier's minimum order quantity and propose a quantity with a short reason. The gateway gives one credential, fallbacks and spend tracking, with no provider keys stored in n8n. Keep a deterministic formula as the default and as the fallback if the model call fails. Validate the output against bounds before inserting it. The human approval step stays mandatory. Send only aggregated sales figures to the model, never customer data."),
    s(3, "At ten times today's volume, what parts of this design would you revisit?", "First, queue mode with more workers, tuned concurrency and a Postgres connection pooler. Second, row-lock contention on hot SKUs during flash sales. Consider batching updates per SKU in each loop batch, or a reservation model. Third, execution data storage: prune more aggressively and avoid saving full payloads. Fourth, webhook ingestion: keep the acknowledgement path minimal, or put a durable queue in front so spikes never threaten store timeouts. At some point, high-volume inventory accounting may belong in a dedicated service, with n8n keeping orchestration, alerting and approvals, where it adds the most value. I would decide that from measured latency and failure data, not from assumptions."),
  ],
  objective: [
    o(5, "For a Respond to Webhook node to send the 200, how must the Webhook node's response setting be configured?", ["Respond immediately","Respond when last node finishes","Using 'Respond to Webhook' node","No response body"], 2, "The Webhook node must be set to respond using the Respond to Webhook node. That lets the workflow persist the event first and then return 200 at a point it chooses."),
    o(5, "Which SQL pattern records an event ID so that a redelivered event is detected as a duplicate?", ["SELECT then INSERT if not found","INSERT … ON CONFLICT DO NOTHING on a unique event_id","UPSERT that overwrites the existing row","DELETE then INSERT"], 1, "A unique key with ON CONFLICT DO NOTHING is atomic. A second delivery inserts nothing, which signals a duplicate without any race."),
    o(4, "How does the workflow know the dedupe insert found a duplicate?", ["Postgres throws a unique-violation error","The webhook header says it is a retry","The insert affected zero rows, for example RETURNING produced no row","The Switch node sees a duplicate flag"], 2, "With ON CONFLICT DO NOTHING, a duplicate inserts no row, so RETURNING produces nothing. The workflow stops on that result."),
    o(4, "What must the HMAC signature be computed over?", ["The JSON re-serialised by n8n","The raw request body bytes exactly as sent","Only the order ID field","The request headers"], 1, "The sender signs the exact bytes it sent. Re-serialised JSON can differ in whitespace or key order, which would break verification."),
    o(3, "How should the computed HMAC be compared with the header value?", ["With a constant-time comparison","With a case-insensitive substring match","By comparing only the first 8 characters","With a regular expression"], 0, "Constant-time comparison, such as crypto.timingSafeEqual, avoids leaking information through timing differences."),
    o(5, "Which condition correctly detects a reorder-point crossing after a sale?", ["new on_hand <= reorder_point","previous on_hand > reorder_point AND new on_hand <= reorder_point","new on_hand < previous on_hand","previous on_hand <= reorder_point"], 1, "Only the transition from above to at-or-below fires. Later sales of an already-low SKU do not alert again."),
    o(4, "A sale of qty 3 returns on_hand = 4 and reorder_point = 5. What should happen?", ["No alert; stock is already low","Alert, because previous stock was 7, which is above 5, and new stock 4 is at or below 5","Alert only if on_hand reaches 0","Reject the update"], 1, "Previous stock is 4 + 3 = 7, which is above 5, and the new value 4 is at or below 5, so this update crossed the threshold."),
    o(4, "A sale of qty 1 returns on_hand = 3 and reorder_point = 5. What should happen?", ["Alert again","Create a second purchase draft","No alert, because previous stock of 4 was already at or below 5","Throw an error"], 2, "Previous stock is 4, which is already at or below the reorder point, so no crossing occurred and no alert is raised."),
    o(5, "Why use a single UPDATE … SET on_hand = on_hand - qty … RETURNING instead of a SELECT then an UPDATE?", ["It is easier to read","It avoids the lost-update race between concurrent orders","It skips the need for an index","It bypasses row locks"], 1, "The read-modify-write happens atomically in one statement under a row lock, so concurrent orders cannot both act on the same stale value."),
    o(4, "Which node routes order-created events and cancellation/refund events down different paths?", ["Merge","Switch","Wait","Execute Workflow"], 1, "A Switch node routes items to different outputs based on a value such as the event type."),
    o(3, "In this blueprint, which node splits an order into line items with SKU, quantity and location?", ["Set/Edit Fields","Respond to Webhook","Error Trigger","Merge"], 0, "The blueprint uses a Set/Edit Fields node to shape the order into line items before Loop Over Items."),
    o(3, "What does the cancellation path do to inventory?", ["Sets on_hand to zero","Adds the line quantity back to on_hand","Deletes the inventory row","Does nothing"], 1, "Cancellations reverse the sale by adding the quantity back, using the same atomic UPDATE pattern."),
    o(4, "Which mechanism most reliably ensures only one open purchase draft per SKU under concurrency?", ["An IF node that checks for an open draft first","A partial unique index on sku WHERE status = 'open', plus ON CONFLICT DO NOTHING","A Wait node before the insert","Running only one n8n worker"], 1, "A database constraint is atomic. A check-then-insert in the workflow can race when two executions run at the same time."),
    o(4, "Where is the error workflow attached to the main workflow?", ["In each node's retry settings","In the main workflow's settings, as its error workflow","In the Respond to Webhook node","In the Postgres credential"], 1, "Each workflow's settings name an error workflow. That workflow starts with an Error Trigger when an execution fails."),
    o(4, "What does n8n queue mode require to distribute executions to workers?", ["Kafka","Redis","RabbitMQ only","A second Postgres server"], 1, "Queue mode uses Redis as the queue from which workers pick up executions."),
    o(3, "In queue mode, what do worker processes do?", ["Store credentials","Pick up and run queued executions","Serve only the editor UI","Replace the database"], 1, "Workers take executions from the Redis queue and run them, which lets throughput scale horizontally."),
    o(3, "Why does the WhatsApp alert use a template message?", ["Templates are cheaper than Slack","Business-initiated messages outside the 24-hour service window must use approved templates","Templates skip authentication","n8n cannot send free text"], 1, "WhatsApp Business rules require pre-approved templates for business-initiated messages outside the customer service window."),
    o(5, "A Postgres decrement times out, but the UPDATE actually committed. Retry-on-fail runs it again. What is the risk?", ["None, because UPDATE is always idempotent","The line is decremented twice unless a per-line idempotency key is used","The row is deleted","The webhook returns 500"], 1, "A relative decrement is not idempotent. Retrying a committed write double-counts unless a movement key blocks the second apply."),
    o(4, "Why return 200 quickly after persisting the event?", ["To save n8n memory","So the store does not time out and resend the event","Because n8n requires it for Loop Over Items","To skip signature checks"], 1, "Slow responses make store platforms retry. A fast acknowledgement after durable persistence avoids needless redeliveries."),
    o(4, "The inventory UPDATE matches no rows for an unknown SKU. What is the correct handling?", ["Ignore it, since nothing changed","Treat it as a failure: route to an error or unmatched path and alert","Insert the SKU with on_hand = 0 silently","Retry indefinitely"], 1, "Zero rows means the line was not applied. Ignoring it would silently drop an update, which the workflow must never do."),
    o(3, "Which n8n Postgres node setting helps ensure a zero-row result still passes an item downstream for checking?", ["Always Output Data","Execute Once","Retry On Fail","Pin Data"], 0, "Always Output Data emits an empty item when there are no results, so an IF node can detect the zero-row case."),
    o(3, "What is the main purpose of Loop Over Items in this workflow?", ["To encrypt line items","To process line items in batches, so large orders or replays do not hit Postgres all at once","To deduplicate events","To send alerts in parallel"], 1, "The node splits items into batches and loops, which smooths load on Postgres."),
    o(3, "How does a Wait node set to resume on a webhook call continue the approval sub-workflow?", ["A buyer replies in Slack","A request hits the execution's resume URL","A Schedule trigger fires","The parent workflow ends"], 1, "The Wait node pauses until its unique resume webhook URL, sent as the approval link, is called."),
    o(3, "How are the Postgres, Slack and WhatsApp credentials handled in n8n?", ["Stored as plain text in workflow JSON","Stored encrypted and referenced by nodes","Typed into each node's parameters","Kept only in Code node variables"], 1, "n8n stores credentials encrypted and nodes reference them, so secrets stay out of the workflow definition."),
    o(2, "If an AI step is added to suggest reorder quantities, what base URL does the OpenAI-compatible chat model use in these blueprints?", ["https://api.openai.com/v1","https://ai-gateway.vercel.sh/v1","https://n8n.cloud/ai","http://localhost:11434"], 1, "These blueprints route model calls through Vercel AI Gateway at that base URL, with an AI Gateway API key."),
    o(3, "Which action best reduces customer PII retained by n8n for this workflow?", ["Turn off HMAC checks","Strip PII early and configure execution data saving and pruning","Send full payloads to Slack","Disable the error workflow"], 1, "Execution logs keep payloads. Minimising fields and pruning saved execution data limits how much PII is retained."),
    o(4, "The event ID is recorded before processing. What does this require when processing later fails?", ["Nothing; the store will resend","A status such as failed, so the event can be replayed despite the dedupe row","Deleting the inventory row","Returning 500 to the store"], 1, "Otherwise the dedupe row would block reprocessing. The error workflow marks the event failed for replay, so nothing is dropped."),
    o(3, "What is the Execute Workflow node used for in this blueprint?", ["Verifying HMAC","Calling the purchase-draft sub-workflow","Starting on schedule","Responding to the webhook"], 1, "Execute Workflow calls the reusable purchase-draft sub-workflow from the main workflow."),
    o(3, "A cancellation arrives for an order whose decrements were never applied. What should happen?", ["Add the stock back anyway","Do not restock; record or park the cancellation until the order state is known","Delete processed_events","Trigger a low-stock alert"], 1, "Restocking without a matching forward movement would inflate inventory. Reversals must be tied to recorded decrements."),
    o(2, "Which fields do the Slack and WhatsApp alerts carry, per the blueprint?", ["Customer name and address","SKU, on-hand count and reorder point","Full order payload","Payment details"], 1, "The alerts include only the SKU, on-hand count and reorder point, which is enough for purchasing and avoids exposing PII."),
  ],
};
export default bank;
